/* kg-theme.js: theme helpers for the explorer - schemaColor (a colour per schema) and band (confidence band).
 * Generated by design/build.py from tokens.json; edit design/src/kg-theme.src.js, then run
 * `python3 design/build.py --inline --export-static`.
 *
 *   KGTHEME.schemaColor(schemaIndex, 'light' | 'dark')  -> '#rrggbb'
 *   KGTHEME.band(confidence)                            -> 'high' | 'medium' | 'low'
 */
(function (root) {
  const THEMES = /*__THEMES__*/null;
  const G = /*__GEOMETRY__*/null;

  /* ---- colour helpers ---- */
  function oklchToHex(L, C, h) {
    const a = C * Math.cos(h * Math.PI / 180), b = C * Math.sin(h * Math.PI / 180);
    const l_ = L + 0.3963377774 * a + 0.2158037573 * b, m_ = L - 0.1055613458 * a - 0.0638541728 * b, s_ = L - 0.0894841775 * a - 1.2914855480 * b;
    const l = l_ ** 3, m = m_ ** 3, s = s_ ** 3;
    const rgb = [4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s, -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s, -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s];
    return '#' + rgb.map(v => { v = v <= 0.0031308 ? 12.92 * v : 1.055 * Math.pow(v, 1 / 2.4) - 0.055; return Math.round(Math.max(0, Math.min(1, v)) * 255).toString(16).padStart(2, '0'); }).join('');
  }
  /* Schemas 0-7 (ordered by table count, largest first) get the curated palette. Schema 8+ gets a generated hue:
     golden-angle steps at fixed OKLCH lightness and chroma, skipping the hues reserved for the accent (brass),
     concept (teal) and polymorphic (magenta). Past ~16 schemas, prefer grouping (see DESIGN.md). */
  function schemaColor(i, theme) {
    const t = THEMES[theme || 'light'];
    if (i < t.schema.length) return t.schema[i];
    let h = (i * 137.508 + 20) % 360, guard = 0;
    while (t.gen['avoid-hue'].some(([a, b]) => h >= a && h <= b) && guard++ < 12) h = (h + 37) % 360;
    return oklchToHex(t.gen.l, t.gen.c, h);
  }
  function band(conf) { return conf >= G.confidence.high.min ? 'high' : conf >= G.confidence.medium.min ? 'medium' : 'low'; }

  root.KGTHEME = root.KG = { THEMES, GEOMETRY: G, schemaColor, band, oklchToHex };
})(typeof window !== 'undefined' ? window : globalThis);
